/**
 * The favicon and the iOS home-screen icon, as base64. The favicon is drawn by
 * tools/favicon.py; the home-screen icon is cut from the logo artwork by
 * tools/brand.py, because at 180 px the globe holds up and at 16 px it does not.
 *
 * /favicon.ico answered 404 on every page view, because every browser asks for
 * it whether or not the page names it. Drawn once by tools/favicon.py and
 * committed, for the same reasons as the share image: no image library in CI,
 * nothing fetched at request time, decoded once per isolate.
 */
const decode = (b64: string): Uint8Array => Uint8Array.from(atob(b64), (ch) => ch.charCodeAt(0));

